#!/usr/bin/env python3
"""Regenerate/check the u-blox configuration key table from the database of the pinned pyubx2."""

import argparse
from pathlib import Path

from generate_expectations import verify_pins
from pyubx2 import UBX_CONFIG_DATABASE

OUTPUT = Path(__file__).resolve().parent / "UBXConfigKeyDatabase.h"


def generate() -> str:
    lines = [
        "// Generated by generate_config_keys.py; do not edit.",
        "#pragma once",
        "",
        "#include <cstdint>",
        "",
        "// clang-format off",
        "namespace UBXConfigKeyDatabase {",
        "/// A configuration key of the u-blox interface descriptions: its type letter there (L, U, I, E, X or R) and the",
        "/// size of its value in bytes.",
        "struct Key { const char* name; uint32_t id; char type; uint8_t size; };",
        "inline constexpr Key keys[] = {",
    ]
    kinds = {}
    for name, (key, kind) in sorted(UBX_CONFIG_DATABASE.items()):
        # pyubx2 names a type by its letter and its size in bytes, such as U004.
        letter, size = kind[0], int(kind[1:])
        if letter not in "LUIEXR" or size not in (1, 2, 4, 8):
            raise RuntimeError(f"{name} has the unknown type {kind}")
        # A key renamed between interface descriptions is listed under both names.
        if kinds.setdefault(key, kind) != kind:
            raise RuntimeError(f"{name} shares the id {key:#010x} with a key of another type")
        lines.append(f"    {{\"{name}\", {key:#010x}, '{letter}', {size}}},")
    lines += ["};", "}  // namespace UBXConfigKeyDatabase", "", "// clang-format on", ""]
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if the table differs")
    args = parser.parse_args()
    verify_pins()
    expected = generate()
    if not args.check:
        OUTPUT.write_text(expected)
    elif not OUTPUT.exists() or OUTPUT.read_text() != expected:
        raise SystemExit(f"{OUTPUT.name} differs; regenerate with the pinned tools")
    else:
        print("Pinned configuration key table matches")


if __name__ == "__main__":
    main()
